/**
 * @summary Filter orders and calculate metrics for an authorized administrator
 */
export const getDukaanAdminOrdersQueryProductNameMax = 100;

export const getDukaanAdminOrdersQueryMinAmountMin = 0;

export const getDukaanAdminOrdersQueryMaxAmountMin = 0;



export const GetDukaanAdminOrdersQueryParams = zod.object({
  "startDate": zod.date().optional(),
  "endDate": zod.date().optional(),
  "shopId": zod.coerce.string().optional(),
  "productName": zod.coerce.string().max(getDukaanAdminOrdersQueryProductNameMax).optional(),
  "status": zod.enum(['pending', 'accepted', 'ready', 'completed', 'cancelled']).optional(),
  "minAmount": zod.coerce.number().min(getDukaanAdminOrdersQueryMinAmountMin).optional(),
  "maxAmount": zod.coerce.number().min(getDukaanAdminOrdersQueryMaxAmountMin).optional()
})

export const GetDukaanAdminOrdersResponse = zod.object({
  "orders": zod.array(zod.object({
  "id": zod.string(),
  "shopId": zod.string(),
  "shopName": zod.string(),
  "productNames": zod.array(zod.string()),
  "total": zod.number(),
  "status": zod.enum(['pending', 'accepted', 'ready', 'completed', 'cancelled']),
  "createdAt": zod.coerce.date()
})),
  "shops": zod.array(zod.object({
  "id": zod.string(),
  "name": zod.string()
})),
  "totalCount": zod.number().int(),
  "averageAmount": zod.number()
})


/**
 * @summary Search customer and merchant accounts for an authorized administrator
 */
export const getDukaanAdminUsersQuerySearchMax = 100;

export const getDukaanAdminUsersQueryOffsetDefault = 0;
export const getDukaanAdminUsersQueryOffsetMin = 0;
export const getDukaanAdminUsersQueryOffsetMax = 100000;



export const GetDukaanAdminUsersQueryParams = zod.object({
  "search": zod.coerce.string().max(getDukaanAdminUsersQuerySearchMax).optional(),
  "offset": zod.coerce.number().int().min(getDukaanAdminUsersQueryOffsetMin).max(getDukaanAdminUsersQueryOffsetMax).default(getDukaanAdminUsersQueryOffsetDefault).describe('Number of matching accounts to skip; each response includes at most 100 accounts.')
})

export const GetDukaanAdminUsersResponse = zod.object({
  "users": zod.array(zod.object({
  "id": zod.string(),
  "name": zod.string(),
  "email": zod.string().email(),
  "role": zod.enum(['customer', 'merchant']),
  "shopName": zod.string().nullable(),
  "shopStatus": zod.union([zod.literal('pending'),zod.literal('approved'),zod.literal('rejected'),zod.literal(null)]).nullable()
})),
  "totalCount": zod.number().int()
})


